catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        g_form.setMandatory('action', false);
        g_form.setDisplay('action', false);

        hideInitialFields();

        return;
    }

    if (newValue) {

        g_form.setDisplay('action', true);
        g_form.setMandatory('action', true);
        g_form.clearOptions('action');
        g_form.addOption('action', '', '--None--');
        g_form.addOption('action', 'add', 'Add a Record');
        g_form.addOption('action', 'modify', 'Modify a Record');
        if (newValue != 'u_market_limit') {
            g_form.addOption('action', 'delete', 'Delete a Record');
        }
        g_form.setValue('action', '');

        g_form.setMandatory('reason_code', false);
        g_form.setMandatory('reason_code_label', false);
        g_form.setMandatory('reason_code_type', false);
        g_form.setMandatory('reason_description', false);
        g_form.setMandatory('reason_dashboard_group', false);

        g_form.setDisplay('reason_code', false);
        g_form.setDisplay('reason_code_label', false);
        g_form.setDisplay('reason_code_type', false);
        g_form.setDisplay('reason_description', false);
        g_form.setDisplay('reason_dashboard_group', false);
    }

    function hideInitialFields() {
        var fieldsToHideInitial = getFieldsToHideInitial();
        fieldsToHideInitial.forEach(function(field) {
            g_form.setMandatory(field, false);
            g_form.setDisplay(field, false);
        });
    }

    function getFieldsToHideInitial() {
        return [
            'old_reason_code', 'reason_code',
            'old_reason_code_label', 'reason_code_label',
            'old_reason_code_type', 'reason_code_type',
            'old_reason_description', 'reason_description',
            'old_reason_dashboard_group', 'reason_dashboard_group',

            'old_location_code', 'location_code',
            'old_location_description', 'location_description',
            'old_region', 'region',

            'old_local_limit', 'local_limit',
            'old_currency', 'currency',
            'old_band_group', 'band_group'
        ];
    }

}
